class OrderRepository:
    def __init__(self):
        self.orders = {}
        self.next_id = 1

    def create(self, request_key, amount):
        """Return (order, created) for an idempotent order request."""
        if not request_key or amount <= 0:
            raise ValueError("request key and positive amount required")
        if request_key in self.orders:
            return dict(self.orders[request_key]), False
        order = {"id": self.next_id, "amount": amount, "state": "pending"}
        self.next_id += 1
        self.orders[request_key] = order
        return dict(order), True

    def count(self):
        return len(self.orders)

    def find(self, request_key):
        order = self.orders.get(request_key)
        return dict(order) if order is not None else None

