def create_order(repository, body):
    """Adapt a repository result to an HTTP-style response tuple."""
    if not isinstance(body, dict):
        return 400, {"error": "object required"}
    request_key = body.get("request_key", "")
    amount = body.get("amount", 0)
    if not isinstance(request_key, str) or not request_key:
        return 400, {"error": "request_key required"}
    if type(amount) is not int or amount <= 0:
        return 400, {"error": "positive integer amount required"}
    order, created = repository.create(request_key, amount)
    status = 201 if created else 200
    return status, {"order": order}


def order_count(repository):
    return 200, {"count": repository.count()}

